#!/bin/bash
# =====================================================
# BonusVarsel AI Regnskap — Redeploy med innebygd HTML
# URL: https://bonusvarsel-ai-regnskap.web.app
# =====================================================
# Kjør: bash ~/Downloads/07_redeploy_ai_regnskap.sh
# =====================================================

set -e

PROJECT_ID="bonusvarsel-ai-regnskap"
DEPLOY_DIR="$HOME/bonusvarsel-regnskap-redeploy"

echo "════════════════════════════════════════════════"
echo "  AI Regnskap — Redeploy"
echo "  → https://bonusvarsel-ai-regnskap.web.app"
echo "════════════════════════════════════════════════"

command -v firebase >/dev/null 2>&1 || { echo "❌ Firebase CLI mangler."; exit 1; }

rm -rf "$DEPLOY_DIR"
mkdir -p "$DEPLOY_DIR/public"

cat > "$DEPLOY_DIR/firebase.json" << 'EOF'
{
  "hosting": {
    "public": "public",
    "ignore": ["firebase.json", "**/.*"],
    "headers": [{ "source": "**", "headers": [{ "key": "Cache-Control", "value": "no-cache" }] }]
  }
}
EOF

cat > "$DEPLOY_DIR/.firebaserc" << EOF
{ "projects": { "default": "$PROJECT_ID" } }
EOF

python3 -c "
import base64
html = base64.b64decode('').decode()
open(\"$DEPLOY_DIR/public/index.html\", \"w\").write(html)
print(\"✅ index.html skrevet\")
"

cd "$DEPLOY_DIR"
firebase use "$PROJECT_ID"
echo "🚀 Deployer AI Regnskap..."
firebase deploy --only hosting --project "$PROJECT_ID"

echo ""
echo "════════════════════════════════════════════════"
echo "  ✅ LIVE!"
echo "  🔗 https://bonusvarsel-ai-regnskap.web.app"
echo "════════════════════════════════════════════════"
